#include <iostream>
#include <cmath>
using namespace std;

struct ac {
    double x, y;
};

ac a[8];

double check(ac a, ac b) {
    return sqrt((a.x - b.x) * (a.x - b.x) +
                (a.y - b.y) * (a.y - b.y));
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    for (int i = 0; i < 8; ++i)
        cin >> a[i].x >> a[i].y;

    ac z, z1;
    z1.x = (a[0].x + a[1].x) / 2.0;
    z1.y = (a[0].y + a[1].y) / 2.0;

    if (a[4].x == a[6].x) {
        z.x = a[4].x;
        z.y = a[5].y;
    } else {
        z.x = a[5].x;
        z.y = a[4].y;
    }

    int vis = 0;
    double d = check(a[4], a[6]) / 2.0;

    for (int i = 0; i < 4; ++i) {
        if (check(a[i], z) <= d)
            vis = 1;
    }

    double d1 = check(a[0], a[2]) / 2.0;

    for (int i = 4; i < 8; ++i) {
        if (check(a[i], z1) <= d1)
            vis = 1;
    }

    cout << (vis ? "YES" : "NO") << '\n';
    return 0;
}

